<style>
:root{color-scheme:light;font-family:system-ui,sans-serif;color:#172033;background:#f5f7fb}body{margin:0;padding:48px 20px}main{max-width:760px;margin:auto}h1{margin-top:0}form,.project-row,.project-detail,.task-row{background:white;border:1px solid #dce2eb;border-radius:10px;padding:18px}form{display:flex;align-items:end;gap:12px;flex-wrap:wrap}label{display:grid;gap:6px;flex:1;min-width:200px;font-weight:600}input,select{font:inherit;padding:10px;border:1px solid #aab4c3;border-radius:6px}button{font:inherit;padding:10px 14px;border:0;border-radius:6px;color:white;background:#3157c8;cursor:pointer}button:hover{background:#2445a7}button:disabled{opacity:.55;cursor:not-allowed}.project-list{display:grid;gap:10px;margin-top:20px}.project-row{display:flex;align-items:center;justify-content:space-between;gap:12px}.actions{display:flex;gap:8px;align-items:center;flex-wrap:wrap}[role=alert]{color:#b42318;margin:12px 0}.back{margin-bottom:20px}.task-row{display:flex;align-items:center;gap:10px;padding:14px 18px}.task-row[hidden]{display:none}.task-row input{padding:0}.summary{font-size:.9rem;color:#46536a}
