const post=(url,body={})=>request(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});
async function showList(error=''){const projects=await request('/api/projects');const filter=new URLSearchParams(location.search).get('filter')||'Active';const shown=projects.filter(p=>Boolean(p.archived)===(filter==='Archived'));
app.innerHTML=`<h1>Workboard</h1><label>Project filter<select id="project-filter"><option${filter==='Active'?' selected':''}>Active</option><option${filter==='Archived'?' selected':''}>Archived</option></select></label><form id="create-form"><label>Project name<input name="name" type="text" autocomplete="off"></label><button>Create project</button></form><div id="message" role="alert" aria-live="polite">${esc(error)}</div><section class="project-list" aria-label="Projects">${shown.map(p=>`<div class="project-row" data-testid="project-row"><span>${esc(p.name)}</span><span class="summary" data-testid="project-summary">${p.completed_count}/${p.total_count} completed</span><div class="actions"><button type="button" data-open="${esc(p.id)}">Open project</button>${p.archived?`<button type="button" data-action="restore" data-id="${esc(p.id)}">Restore project</button>`:`<button type="button" data-action="archive" data-id="${esc(p.id)}">Archive project</button>`}</div></div>`).join('')}</section>`;
app.querySelector('#project-filter').onchange=e=>{history.replaceState({},'',`/?filter=${e.target.value}`);showList()};
app.querySelector('#create-form').onsubmit=async e=>{e.preventDefault();try{await post('/api/projects',{name:new FormData(e.currentTarget).get('name')});history.replaceState({},'','/');await showList()}catch(x){app.querySelector('#message').textContent=x.message}};
app.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>{history.pushState({},'',`/projects/${encodeURIComponent(b.dataset.open)}`);render()});
app.querySelectorAll('[data-action]').forEach(b=>b.onclick=async()=>{await post(`/api/projects/${encodeURIComponent(b.dataset.id)}/${b.dataset.action}`);showList()});}
async function showProject(id){const back=()=>{history.pushState({},'','/');render()};try{const project=await request(`/api/projects/${encodeURIComponent(id)}`);const tasks=await request(`/api/projects/${encodeURIComponent(id)}/tasks`);const archived=Boolean(project.archived);
app.innerHTML=`<button class="back">Projects</button><section class="project-detail"><h1>${esc(project.name)}</h1>${archived?'<p>Archived project</p>':''}</section><form id="rename-form"><label>New project name<input name="name" type="text" autocomplete="off"${archived?' disabled':''}></label><button${archived?' disabled':''}>Rename project</button></form><form id="task-form"><label>Task title<input name="title" type="text" autocomplete="off"${archived?' disabled':''}></label><button${archived?' disabled':''}>Create task</button></form><div id="task-message" role="alert" aria-live="polite"></div><label style="margin-top:18px">Task filter<select id="task-filter"><option>All</option><option>Open</option><option>Completed</option></select></label><section class="project-list" aria-label="Tasks">${tasks.map(t=>`<div class="task-row" data-testid="task-row"><input type="checkbox" ${t.completed?'checked':''}${archived?' disabled':''} aria-label="Complete ${esc(t.title)}" data-task="${esc(t.id)}"><span>${esc(t.title)}</span><label>Task priority<select data-priority="${esc(t.id)}"${archived?' disabled':''}><option${t.priority==='Low'?' selected':''}>Low</option><option${t.priority==='Normal'?' selected':''}>Normal</option><option${t.priority==='High'?' selected':''}>High</option></select></label><form class="task-rename" data-rename="${esc(t.id)}"><label>New task title<input name="title" type="text" autocomplete="off"${archived?' disabled':''}></label><button${archived?' disabled':''}>Rename task</button></form></div>`).join('')}</section>`;
app.querySelector('.back').onclick=back;if(!archived)app.querySelector('#rename-form').onsubmit=async e=>{e.preventDefault();try{await request(`/api/projects/${encodeURIComponent(id)}`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:new FormData(e.currentTarget).get('name')})});showProject(id)}catch(x){app.querySelector('#task-message').textContent=x.message}};const apply=()=>app.querySelectorAll('.task-row').forEach(row=>{const checked=row.querySelector('input').checked,f=app.querySelector('#task-filter').value;row.hidden=f==='Open'?checked:f==='Completed'?!checked:false});app.querySelector('#task-filter').onchange=apply;apply();
app.querySelectorAll('[data-priority]').forEach(select=>select.onchange=async()=>{await request(`/api/projects/${encodeURIComponent(id)}/tasks/${encodeURIComponent(select.dataset.priority)}`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({priority:select.value})})});app.querySelectorAll('[data-task]').forEach(box=>box.onchange=async()=>{await request(`/api/projects/${encodeURIComponent(id)}/tasks/${encodeURIComponent(box.dataset.task)}`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({completed:box.checked})});apply()});
app.querySelectorAll('[data-rename]').forEach(form=>form.onsubmit=async e=>{e.preventDefault();try{await request(`/api/projects/${encodeURIComponent(id)}/tasks/${encodeURIComponent(form.dataset.rename)}`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({title:new FormData(form).get('title')})});showProject(id)}catch(x){app.querySelector('#task-message').textContent=x.message}});
app.querySelector('#task-form').onsubmit=async e=>{e.preventDefault();try{await post(`/api/projects/${encodeURIComponent(id)}/tasks`,{title:new FormData(e.currentTarget).get('title')});showProject(id)}catch(x){app.querySelector('#task-message').textContent=x.message}};
}catch{app.innerHTML='<button class="back">Projects</button><h1>Project not found</h1>';app.querySelector('.back').onclick=back}}
function render(){const m=location.pathname.match(/^\/projects\/([^/]+)\/?$/);m?showProject(decodeURIComponent(m[1])):showList()}addEventListener('popstate',render);render();
</script></body></html>
